/**
 * `Env` is generated by `wrangler types` (see package.json `types` script)
 * into `worker-configuration.d.ts`, gitignored and regenerated from
 * `wrangler.toml`. Re-exported through the `Cloudflare` namespace rather than
 * the bare global `Env` identifier — aliasing `Env` to itself in the same
 * module (`export type Env = Env`) is a circular reference once this file
 * declares its own `Env`, since a module-scope declaration shadows the
 * ambient global for every reference in the file, hoisting included.
 * `Cloudflare.Env` names the same generated shape without that trap.
 */
/**
 * `VECTORIZE` (issue #38) is declared here by hand, as **optional**, and
 * deliberately stays that way now that the `[[vectorize]]` blocks in
 * `wrangler.toml` are uncommented and `wrangler types` emits the binding
 * itself.
 *
 * It was originally hand-declared out of necessity: with the blocks
 * commented out, `wrangler types` emitted no `VECTORIZE` at all and every
 * `env.VECTORIZE` reference in `search/vectorize.ts` stopped compiling. That
 * necessity is gone. The declaration is kept because optional is the
 * truthful shape, and a more useful one than the generated type gives.
 *
 * `search/vectorize.ts` has always branched on `if (!env.VECTORIZE)` to fall
 * back to FTS. That branch is the feature's safety net and it is exercised
 * by tests that stub the binding away entirely. Against a generated
 * non-optional binding it would be unreachable-by-type — the compiler would
 * let it rot, or flag it as dead. Declaring it optional keeps the fallback a
 * live, type-checked path.
 *
 * The intersection is correct either way: where `wrangler types` emits a
 * non-optional `VECTORIZE`, the generated property narrows this one.
 */
export type Env = Cloudflare.Env & { VECTORIZE?: VectorizeIndex };

/** One of the five bindings `/health` and `assertBindings` care about. */
type CheckedBinding = "DB" | "BUCKET" | "KV" | "AI" | "ASSETS" | "EMAIL";

export interface AssertBindingsResult {
  ok: boolean;
  checks: Record<CheckedBinding, "ok" | "missing" | "degraded">;
}

/**
 * Cheap presence check for every binding the Worker depends on, used by
 * `GET /health`. `EMAIL` missing is `"degraded"` rather than failing the
 * whole check: Cloudflare Email Service enablement and the keepsake.ing
 * sender domain onboarding are unverified as of the plan (Risks #1), and a
 * Worker that can serve the feed and take listings shouldn't report itself
 * down just because notification email isn't wired up yet.
 */
export function assertBindings(env: Env): AssertBindingsResult {
  const checks = {
    DB: env.DB ? "ok" : "missing",
    BUCKET: env.BUCKET ? "ok" : "missing",
    KV: env.KV ? "ok" : "missing",
    AI: env.AI ? "ok" : "missing",
    ASSETS: env.ASSETS ? "ok" : "missing",
    EMAIL: env.EMAIL ? "ok" : "degraded",
  } satisfies Record<CheckedBinding, "ok" | "missing" | "degraded">;

  const ok = (Object.entries(checks) as [CheckedBinding, string][]).every(
    ([binding, status]) => binding === "EMAIL" || status === "ok",
  );

  return { ok, checks };
}

/**
 * `wrangler types` generates a single string-literal type for a `[vars]`
 * entry from whatever value is currently in `wrangler.toml` (e.g. `MOCK_AI:
 * "0"`) rather than the general `string` you'd get from a real env var at
 * runtime — so `env.MOCK_AI === "1"` doesn't type-check as written even
 * though the deployed value absolutely can be `"1"` (`.dev.vars`, `wrangler
 * dev --var`, a different environment block). Centralized here instead of an
 * `as string` at every call site.
 */
export function isMockAi(env: Env): boolean {
  return (env.MOCK_AI as string) === "1";
}

/** Same widening trick as `isMockAi`: `wrangler types` gives `EMAIL_PROVIDER`
 * a single string-literal type matching whatever's currently in
 * `wrangler.toml` (`"cf"`), so comparing it against `"resend"` doesn't
 * type-check as written even though a real deploy can set either. Returns
 * `undefined` for anything that isn't one of the two providers `sendMail`
 * knows how to use, rather than throwing — an unrecognized value should fall
 * through to the stub-log path, not 500 every send. */
export type EmailProviderName = "cf" | "resend";

export function emailProviderName(env: Env): EmailProviderName | undefined {
  const value = env.EMAIL_PROVIDER as string;
  return value === "cf" || value === "resend" ? value : undefined;
}

/**
 * The one place `ENVIRONMENT === "production"` is decided. Same widening
 * trick as `isMockAi`: `wrangler types` narrows `ENVIRONMENT` to the literal
 * currently in `wrangler.toml`'s top-level `[vars]` (`"development"`), so a
 * bare comparison against `"production"` doesn't typecheck even though the
 * deployed value obviously can be that.
 *
 * Centralized because more than one thing now branches on it and they must
 * never disagree: `/robots.txt` (production serves the static allow-list,
 * everything else a blanket disallow), `/sitemap.xml` (404 off production),
 * the `X-Robots-Tag` response header, and `/health`'s `degraded` verdict.
 * Getting one of those right and another wrong is exactly the shape of
 * launch audit finding 2.
 */
export function isProduction(env: Env): boolean {
  return (env.ENVIRONMENT as string) === "production";
}

/**
 * Issue #38's kill switch: is semantic search (Vectorize + Workers AI
 * embeddings) allowed to run at all?
 *
 * **On in every environment** as of 2026-09-07, after the two things this
 * comment used to say it must wait for were actually done with a real
 * credential (recorded in `docs/runbooks/deploy.md` → "Vectorize / semantic
 * search"): the three indexes were confirmed to exist at `768 / cosine`, and
 * `MIN_SCORE` was re-derived against the real embedding model
 * (`docs/design/min-score-calibration.md`).
 *
 * It stays a kill switch. Setting it back to `"0"` is the first thing to try
 * if search misbehaves: with it off, `GET /api/feed?q=` behaves exactly as it
 * does without any of this — FTS5 via `db/fts.ts`, the fallback path the
 * issue asked to keep rather than replace — and no embedding call, Vectorize
 * call or AI budget spend happens on either the read or the write path.
 * `test/search.test.ts` asserts that equivalence against a no-binding control
 * rather than assuming it.
 *
 * One thing to know before switching it off: `reembedListing` runs only on
 * listing create/edit and on the #37 aspects backfill, so any listing created
 * while this is `"0"` has no vector and is invisible to vector search until
 * it is next written. See the runbook section above for the backfill that
 * does not exist.
 *
 * Opt-in on `"1"` only — an unset, empty, malformed or absent var reads as
 * off, so no environment can enable this by accident or by omission. Same
 * string-literal widening as `isMockAi` above.
 */
export function semanticSearchEnabled(env: Env): boolean {
  return (env.SEMANTIC_SEARCH as string | undefined) === "1";
}

/**
 * True in the two environments that run as a deployed Worker on Cloudflare —
 * `preview` and `production` — and false for local `wrangler dev`, `vitest`
 * and Playwright.
 *
 * The distinction `isProduction` draws is "is this the public site"; this one
 * is "is this configured infrastructure, where a missing binding or secret is
 * a defect rather than the normal state". Issue #123 needed the second: the
 * zone cache purge is *expected* to be unconfigured locally and in tests, so
 * skipping it there is silent, but a skip on a deployed Worker means the
 * credential is damaged and has to be loud. Kept beside `isProduction` so the
 * two string comparisons that decide environment live in one place and cannot
 * drift apart.
 */
export function isDeployed(env: Env): boolean {
  const environment = env.ENVIRONMENT as string;
  return environment === "production" || environment === "preview";
}

/**
 * Parse an integer-shaped [vars] entry (all Worker vars are strings), falling
 * back when the value is missing or not a valid integer rather than throwing
 * — a malformed budget var should degrade to a safe default, not 500 the
 * Worker on every request that reads it.
 */
export function parseIntVar(name: string, value: string | undefined, fallback: number): number {
  if (value === undefined) return fallback;
  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed)) {
    console.warn(`parseIntVar: ${name}=${JSON.stringify(value)} is not an integer, using fallback ${fallback}`);
    return fallback;
  }
  return parsed;
}

/**
 * Issue #39's floor: an aspect value needs at least this many approved
 * listings before `GET /api/feed/shelves` renders it as a shelf. Same
 * value in every environment (unlike the moderation budgets above, which
 * scale with real traffic) — a shelf's usefulness threshold is about how
 * many items make a group read as a deliberate collection rather than a
 * coincidence, and that doesn't change with deploy target. Default `3`:
 * `2` reads as an accident ("two things happen to share a word"), and the
 * plan's own worry is a shelf that looks broken holding one item — three is
 * the smallest count that reliably reads as "a shelf" rather than "a
 * coincidence" once there's a real catalogue, while still being reachable
 * at today's tiny one.
 */
export function shelfMinItems(env: Env): number {
  return parseIntVar("SHELF_MIN_ITEMS", env.SHELF_MIN_ITEMS as string | undefined, 3);
}

/**
 * How many distinct reporters take a live listing down on their own
 * (`POST /api/listings/:id/reports` in `src/routes/listings.ts`).
 *
 * Lives here rather than beside the route that enforces it because
 * `GET /api/admin/health` has to report the same number back — issue #89:
 * an auto-hide pages nobody today, so the health payload now names both the
 * listings this threshold has already hidden and the ones one report away
 * from it. Two copies of `3` that could drift is exactly how a "listings
 * near the threshold" counter ends up counting the wrong listings.
 */
export const DEFAULT_REPORT_AUTOHIDE_THRESHOLD = 3;

export function reportAutohideThreshold(env: Env): number {
  return parseIntVar(
    "REPORT_AUTOHIDE_THRESHOLD",
    env.REPORT_AUTOHIDE_THRESHOLD as string | undefined,
    DEFAULT_REPORT_AUTOHIDE_THRESHOLD,
  );
}
